use crate::{
    logging::{aztecnr_debug_log_format, aztecnr_warn_log_format},
    messages::{
        discovery::{ComputeNoteHash, ComputeNoteNullifier, nonce_discovery::attempt_note_nonce_discovery},
        encoding::MAX_MESSAGE_CONTENT_LEN,
        logs::note::{decode_private_note_message, MAX_NOTE_PACKED_LEN},
        processing::enqueue_note_for_validation,
    },
    protocol::{address::AztecAddress, constants::MAX_NOTE_HASHES_PER_TX, traits::ToField},
};

/// Processes a private note message, attempting to discover and enqueue any notes it contains.
///
/// For each note recovered from the message whose computed note hash matches a unique note hash in the transaction,
/// a [`NoteValidationRequest`](crate::messages::processing::NoteValidationRequest) is pushed onto the ephemeral array
/// at `NOTE_VALIDATION_REQUESTS_ARRAY_BASE_SLOT` via
/// [`enqueue_note_for_validation`](crate::messages::processing::enqueue_note_for_validation). PXE later drains this
/// array during `validate_and_store_enqueued_notes_and_events`, after which the notes are retrievable via `get_notes`.
///
/// Messages that fail to decode, or whose computed note hash matches nothing in the transaction, are discarded
/// (with a debug or warning log respectively) and produce no validation requests. Decode failures are not treated
/// as errors since messages may originate from malicious senders and we don't want them to be able to brick message
/// processing.
///
/// ## Use Cases
///
/// This function is invoked automatically by aztec-nr when handling messages with the built-in private note type id,
/// so contracts do not normally need to call it directly. It is exposed for use by custom message handlers (see
/// [`CustomMessageHandler`](crate::messages::discovery::CustomMessageHandler)) that might want to use the standard
/// note message processing pipeline while extending it with custom logic.
pub unconstrained fn process_private_note_msg(
    contract_address: AztecAddress,
    tx_hash: Field,
    unique_note_hashes_in_tx: BoundedVec<Field, MAX_NOTE_HASHES_PER_TX>,
    first_nullifier_in_tx: Field,
    compute_note_hash: ComputeNoteHash,
    compute_note_nullifier: ComputeNoteNullifier,
    msg_metadata: u64,
    msg_content: BoundedVec<Field, MAX_MESSAGE_CONTENT_LEN>,
) {
    let decoded = decode_private_note_message(msg_metadata, msg_content);

    if decoded.is_some() {
        let (note_type_id, owner, storage_slot, randomness, packed_note) = decoded.unwrap();

        attempt_note_discovery(
            contract_address,
            tx_hash,
            unique_note_hashes_in_tx,
            first_nullifier_in_tx,
            compute_note_hash,
            compute_note_nullifier,
            owner,
            storage_slot,
            randomness,
            note_type_id,
            packed_note,
        );
    } else {
        aztecnr_warn_log_format!(
            "Could not decode private note message from tx {0}, ignoring",
        )(
            [tx_hash],
        );
    }
}

/// Attempts discovery of a note given information about its contents and the transaction in which it is suspected the
/// note was created.
unconstrained fn attempt_note_discovery(
    contract_address: AztecAddress,
    tx_hash: Field,
    unique_note_hashes_in_tx: BoundedVec<Field, MAX_NOTE_HASHES_PER_TX>,
    first_nullifier_in_tx: Field,
    compute_note_hash: ComputeNoteHash,
    compute_note_nullifier: ComputeNoteNullifier,
    owner: AztecAddress,
    storage_slot: Field,
    randomness: Field,
    note_type_id: Field,
    packed_note: BoundedVec<Field, MAX_NOTE_PACKED_LEN>,
) {
    let discovered_notes = attempt_note_nonce_discovery(
        unique_note_hashes_in_tx,
        first_nullifier_in_tx,
        compute_note_hash,
        compute_note_nullifier,
        contract_address,
        owner,
        storage_slot,
        randomness,
        note_type_id,
        packed_note,
    );

    if discovered_notes.len() == 0 {
        // A private note message that results in no discovered notes means none of the computed note hashes matched
        // any unique note hash in the transaction. This could indicate a malformed or malicious message (e.g. a sender
        // providing bogus note content).
        aztecnr_warn_log_format!(
            "Discarding private note message from tx {0} for contract {1}: no matching note hash found in the tx",
        )(
            [tx_hash, contract_address.to_field()],
        );
    } else {
        aztecnr_debug_log_format!(
            "Discovered {0} notes from a private message for contract {1}",
        )(
            [discovered_notes.len() as Field, contract_address.to_field()],
        );
    }

    discovered_notes.for_each(|discovered_note| {
        enqueue_note_for_validation(
            contract_address,
            owner,
            storage_slot,
            randomness,
            discovered_note.note_nonce,
            packed_note,
            discovered_note.note_hash,
            discovered_note.inner_nullifier,
            tx_hash,
        );
    });
}

155.source:
use crate::messages::{
    discovery::{
        ComputeNoteHash, ComputeNoteNullifier, CustomMessageHandler, private_events::process_private_event_msg,
        private_notes::process_private_note_msg,
    },
    encoding::{decode_message, MESSAGE_CIPHERTEXT_LEN, MESSAGE_PLAINTEXT_LEN},
    encryption::{aes128::AES128, message_encryption::MessageEncryption},
    msg_type::{
        MIN_CUSTOM_MSG_TYPE_ID, PARTIAL_NOTE_PRIVATE_MSG_TYPE_ID, PRIVATE_EVENT_MSG_TYPE_ID, PRIVATE_NOTE_MSG_TYPE_ID,
    },
    processing::ResolvedTx,
};

use crate::logging::{aztecnr_debug_log, aztecnr_warn_log_format};
use crate::partial_notes::process_partial_note_private_msg;
use crate::protocol::address::AztecAddress;

/// Processes a message that can contain notes, partial notes, or events.
///
/// Notes result in nonce discovery being performed prior to delivery, which requires knowledge of the transaction hash
/// in which the notes would've been created (typically the same transaction in which the log was emitted), along with
/// the list of unique note hashes in said transaction and the `compute_note_hash` and `compute_note_nullifier`
/// functions. Once discovered, the notes are enqueued for validation.
///
/// Partial notes result in a pending partial note entry being stored in a PXE capsule, which will later be retrieved
/// to search for the note's completion public log.
///
/// Events are processed by computing an event commitment from the serialized event data and its randomness field, then
/// enqueueing the event data and commitment for validation.
pub unconstrained fn process_message_ciphertext(
    contract_address: AztecAddress,
    compute_note_hash: ComputeNoteHash,
    compute_note_nullifier: ComputeNoteNullifier,
    process_custom_message: Option<CustomMessageHandler>,
    message_ciphertext: BoundedVec<Field, MESSAGE_CIPHERTEXT_LEN>,
    resolved_tx: ResolvedTx,
    recipient: AztecAddress,
) {
    let message_plaintext_option = AES128::decrypt(message_ciphertext, recipient, contract_address);

    if message_plaintext_option.is_some() {
        process_message_plaintext(
            contract_address,
            compute_note_hash,
            compute_note_nullifier,
            process_custom_message,
            message_plaintext_option.unwrap(),
            resolved_tx,
            recipient,
        );
    } else {
        aztecnr_warn_log_format!("Could not decrypt message ciphertext from tx {0}, ignoring")([resolved_tx.tx_hash]);
    }
}

pub(crate) unconstrained fn process_message_plaintext(
    contract_address: AztecAddress,
    compute_note_hash: ComputeNoteHash,
    compute_note_nullifier: ComputeNoteNullifier,
    process_custom_message: Option<CustomMessageHandler>,
    message_plaintext: BoundedVec<Field, MESSAGE_PLAINTEXT_LEN>,
    resolved_tx: ResolvedTx,
    recipient: AztecAddress,
) {
    // The first thing to do after decrypting the message is to determine what type of message we're processing. We
    // have 3 message types: private notes, partial notes and events.

    // We decode the message to obtain the message type id, metadata and content.
    let decoded = decode_message(message_plaintext);

    if decoded.is_some() {
        let (msg_type_id, msg_metadata, msg_content) = decoded.unwrap();

        if msg_type_id == PRIVATE_NOTE_MSG_TYPE_ID {
            aztecnr_debug_log!("Processing private note msg");

            process_private_note_msg(
                contract_address,
                resolved_tx.tx_hash,
                resolved_tx.unique_note_hashes_in_tx,
                resolved_tx.first_nullifier_in_tx,
                compute_note_hash,
                compute_note_nullifier,
                msg_metadata,
                msg_content,
            );
        } else if msg_type_id == PARTIAL_NOTE_PRIVATE_MSG_TYPE_ID {
            aztecnr_debug_log!("Processing partial note private msg");

            process_partial_note_private_msg(
                contract_address,
                msg_metadata,
                msg_content,
                resolved_tx,
                recipient,
            );
        } else if msg_type_id == PRIVATE_EVENT_MSG_TYPE_ID {
            aztecnr_debug_log!("Processing private event msg");

            process_private_event_msg(
                contract_address,
                msg_metadata,
                msg_content,
                resolved_tx.tx_hash,
            );
        } else if msg_type_id < MIN_CUSTOM_MSG_TYPE_ID {
            // The message type ID falls in the range reserved for aztec.nr built-in types but wasn't matched above.
            // This most likely means the message is malformed or a custom message was incorrectly assigned a reserved
            // ID. Custom message types must use IDs allocated via `custom_msg_type_id`.
            aztecnr_warn_log_format!(
                "Message type ID {0} is in the reserved range but is not recognized, ignoring. See https://docs.aztec.network/errors/3",
            )(
                [msg_type_id as Field],
            );
        } else if process_custom_message.is_some() {
            process_custom_message.unwrap()(
                contract_address,
                msg_type_id,
                msg_metadata,
                msg_content,
                resolved_tx,
                recipient,
            );
        } else {
            // A custom message was received but no handler is configured. This likely means the contract emits custom
            // messages but forgot to register a handler via `AztecConfig::custom_message_handler`.
            aztecnr_warn_log_format!(
                "Received custom message with type id {0} but no handler is configured, ignoring. See https://docs.aztec.network/errors/2",
            )(
                [msg_type_id as Field],
            );
        }
    } else {
        aztecnr_warn_log_format!("Could not decode message plaintext from tx {0}, ignoring")([resolved_tx.tx_hash]);
    }
}

