use crate::{messages::encoding::MESSAGE_CIPHERTEXT_LEN, oracle::offchain_effect::emit_offchain_effect};
use crate::protocol::{address::AztecAddress, hash::poseidon2_hash_bytes, traits::ToField};

// The following identifier was copied over to `yarn-project/stdlib/src/tx/offchain_effect.ts`. If you modify it don't
// forget to update it there as well.
pub global OFFCHAIN_MESSAGE_IDENTIFIER: Field =
    comptime { poseidon2_hash_bytes("aztecnr_offchain_message".as_bytes()) };

/// Emits a message that will be delivered offchain rather than through the data availability layer.
///
/// Sends data through an alternative app-specific channel without incurring data availability (DA) costs. After
/// receiving the message, the recipient is expected to call the `offchain_receive` utility function (injected by the
/// `#[aztec]` macro) on the contract that originally emitted the message.
///
/// # Example use case
///
/// A typical use case would be a payment app where the notes and events do not need to be delivered via DA because the
/// payment is considered successful by the recipient once he receives the notes and events offchain. Hence having the
/// guaranteed delivery via DA is not necessary.
///
/// # When not to use
///
/// This function should not be used when an onchain guarantee of successful delivery is required. This is the case
/// when a smart contract (rather than a person) needs to make decisions based on the message. For example, consider a
/// contract that escrows a privately-stored NFT (i.e. an NFT represented by a note) and releases it to a buyer only
/// after receiving a payment in a specific token. Without onchain delivery, the buyer could potentially obtain the NFT
/// without sending the payment token message (the note hash preimage) to the seller, rugging the seller.
///
/// To clarify the above, while the malicious buyer's payment token would still be deducted from their balance, they
/// would obtain the NFT while the seller would be unable to spend the payment token, keeping the payment token note in
/// limbo.
///
/// # Arguments
///
/// * `message` - The message to emit.
/// * `recipient` - The address of the recipient.
pub fn deliver_offchain_message(ciphertext: [Field; MESSAGE_CIPHERTEXT_LEN], recipient: AztecAddress) {
    // Safety: Offchain effects are by definition unconstrained. They are emitted via an oracle which we don't use for
    // anything besides its side effects, therefore this is safe to call.
    unsafe {
        emit_offchain_effect(
            [OFFCHAIN_MESSAGE_IDENTIFIER, recipient.to_field()].concat(ciphertext),
        )
    };
}

